function ageTipsWin:closeRuleInfo()
  if ageTipsWin.panel then
    ageTipsWin.panel:getRootLayer():removeFromParentAndCleanup(true)
    ageTipsWin.panel = nil
  end
end

function ageTipsWin:initListView()
  local posX, posY = self.ui.content_rights:getPosition()
  local size = self.ui.content_rights:getContentSize()
  local dragListConfig = {
    cliprect = CCRectMake(0, 0, size.width, size.height),
    noshade = true,
    container = self.ui.content_rights,
    priority = self.mainTouchPriority - 5,
    zorder = 99,
    mcpMode = true
  }
  self.dragList = ed.draglist.create(dragListConfig)
end

function ageTipsWin:addTextItem(text, color)
  local size = self.ui.content_rights:getContentSize()
  local posY = size.height
  local width = size.width
  local gapY = 8
  local label = richText:new()
  label:setString(string.format("<text|%s|%s|%d>", color, text, width))
  label:setAnchorPoint(ccp(0, 0.5))
  local width, height = label:getSize()
  label.rootNode:setPosition(ccp(0, posY - (self.itemTotalH + gapY) - height / 2))
  self.itemTotalH = self.itemTotalH + height + gapY
  self.dragList:addItem(label.rootNode)
  self.dragList:initListHeight(self.itemTotalH)
end

function ageTipsWin:addBody(text)
  self:addTextItem(text, "normalButton")
end

function ageTipsWin:addEventListen()
  self:btRegisterButtonClick({
    button = self.ui.closeBtn,
    press = self.ui.closeBtn_press,
    clickHandler = function()
      self:destroy({skipAnim = true})
    end
  })
end
